// ---- "back" layout aim (camera over the bowl) ------------------------------
CAM_MOUNT_Y  = -68;   // camera/board position along the drum axis; pushed FORWARD of
                      // the funnel so the tilted screen never touches the funnel flare
CAM_MOUNT_Z  =  62;   // camera/board height above the drum centre (raised clear of
                      // the funnel so the owner can read the screen unobstructed)
PET_FACE_Y   = -80;   // where the pet's face is as it eats (over the bowl, -Y)
PET_FACE_Z   = -34;   // pet-face height (down over the food, off the front rim)
// Look-at tilt about X that rotates the camera's -Z axis onto the target.
// atan2(dy, -dz) comes out NEGATIVE here => tilts FORWARD toward -Y (the pet),
// which is the whole point -- the old +24 tilted it BACK toward the drum.
CAM_TILT     = atan2(PET_FACE_Y - CAM_MOUNT_Y, CAM_MOUNT_Z - PET_FACE_Z);

input.new_string:
// ---- "back" layout aim (WEDGE STAND over the bowl) -------------------------
// The board rides the same printable 30-degree wedge stand as the desk part
// (board_cradle_stand), lifted on a short pedestal that rises from the base.
// The pedestal gives the HEIGHT; the wedge gives the 30-degree TILT; together
// the camera on the board's underside looks down-and-forward onto the pet.
PET_FACE_Y   = -80;   // where the pet's face is as it eats (over the bowl, -Y)
PET_FACE_Z   = -34;   // pet-face height (down over the food, off the front rim)
WEDGE_Y      = -28;   // wedge-stand centre, cantilevered forward over the bowl
PED_TOP      =  20;   // pedestal platform height the wedge sits on (base +124mm)
// With BM_TILT=30, a wedge at (0,WEDGE_Y,PED_TOP) puts its camera near
// (0,WEDGE_Y,PED_TOP+BM_LIFT) aimed almost exactly onto (0,PET_FACE_Y,PET_FACE_Z).
// (legacy back-layout single-board params, kept for the front layout / reference)
CAM_MOUNT_Y  = -68;
CAM_MOUNT_Z  =  62;
CAM_TILT     = atan2(PET_FACE_Y - CAM_MOUNT_Y, CAM_MOUNT_Z - PET_FACE_Z);

