import sys, os, glob

def bbox(fn):
    xs = ys = zs = None
    pts = []
    with open(fn) as f:
        for line in f:
            line = line.strip()
            if line.startswith('vertex '):
                pts.append(tuple(float(v) for v in line.split()[1:4]))
    xs = [p[0] for p in pts]; ys = [p[1] for p in pts]; zs = [p[2] for p in pts]
    return (min(xs), max(xs), min(ys), max(ys), min(zs), max(zs), len(pts))

for fn in sorted(glob.glob(os.path.join(sys.argv[1], '*.stl'))):
    x0, x1, y0, y1, z0, z1, n = bbox(fn)
    print(f"{os.path.basename(fn):<22} X {x0:8.2f}..{x1:7.2f}   "
          f"Y {y0:8.2f}..{y1:7.2f}   Z {z0:8.2f}..{z1:7.2f}   "
          f"(overlap {x1-x0:.2f} x {y1-y0:.2f} x {z1-z0:.2f})")

