// ---- CLEARING THE DRUM (this cost a rebuild -- do not undo it) --------------
// The chute used to be tucked UP into the outlet: floor top at z=-31, rails 15mm
// tall all the way to the back. Both fouled the feeder, confirmed by CGAL
// (chute INTERSECT housing = 36 x 29 x 9.3mm at Y 9.96..39; chute INTERSECT rotor
// = a 3 x 1.5 x 1.4mm bite at Y 37..38.5). Three separate causes:
//   1. the trough is 36mm wide (X +/-18) but the outlet slot is only 34 (X +/-17),
//      so the outer 1mm strip each side rode into the drum's bottom wall;
//   2. 15mm rails reached z=-18, straight through the wall (which at x~17..18
//      spans z -27..-23.5) and on into the bore;
//   3. the back lip sat at Y 37..39.5, but the slot STOPS at Y=36 -- it was under
//      solid rim, and clipped a rotor vane.
// The fix keeps the trough full width and instead puts the whole floor BELOW the
// drum: the drum's lowest point is z=-32 (x=0), so a floor topping out at -33 is
// clear at every x, and 1mm is far too small for kibble to escape sideways.
// The rails then taper -- short at the back where the drum curves down over them,
// full height once they are forward of it. The binding point is a rail's INNER
// top corner at (x=16, z=-29.5): radius 33.55 vs the drum's 32, so 1.55mm clear.
// The back lip moves behind Y=39.5, past the end of the drum, where it can rise
// freely again.
CHUTE_FY = BOWL_CY + 52;   // chute delivery point (front end), follows the bowl
CHUTE_FZ = -72;            // front-end height: sets the slope (19.6deg)
CHUTE_BZ = -35;            // back-end floor underside; +2 for the floor -> top -33
CHUTE_RB = 5.5;            // rail height at the BACK -- limited by the drum's curve
module chute() {
    color("Silver") {
        // Sloped trough FLOOR. The back edge sits at Y=36 so it underlies the
        // WHOLE outlet (world-Y 3..36) -- the old back at Y=22 let the rear third
        // of every pocket-dump spill behind the chute. It now runs back to Y=40,
        // past the drum's end, so bounced kibble still lands on it.
        hull() {
            translate([-18, 36, CHUTE_BZ]) cube([36, 4, 2]);         // back, under the outlet
            translate([-18, CHUTE_FY, CHUTE_FZ]) cube([36, 2, 2]);   // front, launches into the bowl
        }
        for (sx = [-18, 16])                                 // side rails (trough walls)
            hull() {
                translate([sx, 36, CHUTE_BZ]) cube([2, 4, CHUTE_RB]);
                translate([sx, CHUTE_FY, CHUTE_FZ]) cube([2, 2, 15]);
            }
        // back lip: stops food rolling off the rear of the floor. Sits BEHIND the
        // drum (which ends at Y=39), so it is free to stand full height.
        translate([-18, 39.5, CHUTE_BZ]) cube([36, 2.5, 6]);
        // two legs down to the base plate -- anchor the chute to the frame (they
        // sit BEHIND the bowl near-rim, so they clear the dish)
        for (sx = [-18, 14])
            translate([sx, 35, STAND_BASE_Z - 4]) cube([4, 4, CHUTE_BZ - (STAND_BASE_Z - 4)]);
    }
}

