// span X 30..42 (SUPP_W/2 = 42, arched out to +/-30) -> 36; the chute legs are
// at X -18..-14 and 14..18 -> +/-16, Y 35..39 -> 37; the pedestal posts are at
// X +/-48, Y -68..-58 -> -63.
FEET_SUPPORT = [[-36, SUPP_Y1], [36, SUPP_Y1], [-36, SUPP_Y2], [36, SUPP_Y2]];
FEET_CHUTE   = [[-16, 37], [16, 37]];
// Only the "back" layout is split. mount_front() keeps its old fused foot --
// the front layout is legacy (the whole camera aim solve is done for "back")
// and splitting it would put screw holes under the bowl.
FEET_PED     = (LAYOUT == "front") ? [] : [[-48, -63], [48, -63]];
FEET_ALL     = concat(FEET_SUPPORT, FEET_CHUTE, FEET_PED);

// bolt-down flange grown at the base of a tower leg (part of the TOWER)
module tower_foot(p) {
    translate([p[0], p[1], STAND_BASE_Z])
        difference() {
            translate([-FOOT_W/2, -FOOT_L/2, 0]) cube([FOOT_W, FOOT_L, FOOT_T]);
            for (s = [-1, 1])
                translate([0, s * FOOT_S, -0.1])
                    cylinder(d = FOOT_PILOT, h = FOOT_T - 1, $fn = 24);
        }
}
// relief pocket in the PLATE so a flange seats flat on the floor. Over most of
// the tray this cuts nothing (the floor is already the lowest surface); it earns
// its keep where a flange lands on the bowl ring -- the pedestal feet at X
// +/-48 sit right on the ring's rear arc, so the ring is notched for them. That
// is fine: the flange bolted into the notch locates the bowl there instead.
module foot_pocket(p) {
    translate([p[0] - (FOOT_W/2 + FOOT_FIT), p[1] - (FOOT_L/2 + FOOT_FIT),
               STAND_BASE_Z - 0.01])
        cube([FOOT_W + 2*FOOT_FIT, FOOT_L + 2*FOOT_FIT, 12]);
}
// the matching countersunk clearance pair through the plate floor
module foot_holes(p) {
    for (s = [-1, 1])
        translate([p[0], p[1] + s * FOOT_S, 0]) {
            translate([0, 0, STAND_BASE_Z - STAND_BASE_T - 1])
                cylinder(d = FOOT_SCREW, h = STAND_BASE_T + 4, $fn = 24);
            translate([0, 0, STAND_BASE_Z - STAND_BASE_T - 0.01])
                cylinder(d1 = FOOT_CSK, d2 = FOOT_SCREW,
                         h = (FOOT_CSK - FOOT_SCREW) / 2, $fn = 24);
        }
}

