// that. It is 30 seconds, and it buys a drive that does not rattle.
translate([0, 0, -0.1])
    intersection() {
        cylinder(d = STEP_SHAFT_D + 0.4, h = STEP_SHAFT_LEN + 0.6);
        cube([STEP_SHAFT_D + 1, STEP_SHAFT_FLAT + 0.35, 2 * (STEP_SHAFT_LEN + 1)],
