// WORST-CASE seat check at FDM tolerance -- the reason BM_FIT moved to 1.0/side.
//
// Same idea as fit_board_worst.scad but with JLCPCB's FDM number, not MJF's:
// a pocket printed 0.5mm undersize all round is the same thing as a case 0.5mm
// oversize, so probe with the case grown 0.5 per side. Empty result == the case
// still drops in at the bad corner of the FDM tolerance box.
//
// The old 0.6/side pocket would have left 0.1mm here. This must be clear by
// 0.5mm, and "clear" is all an intersection can tell us -- see the clearance
// arithmetic printed by fit_board_margin.scad's comment block below.
use <D:/openVela/contest2026_043_CircuitForge/hardware/velapaw_feeder.scad>

GROW = 0.5;   // per side -- JLCPCB FDM tolerance
BM_W = 95.11; BM_H = 63.67; BM_R = 7.30;

// The pocket has R7.30 corners. A square-cornered probe pokes outside them and
// reports a false hit -- that is exactly how the first version of the MJF probe
// lied. Build the case as a hull of four circles so its corners match.
module case_rrect(w, h, r, t) {
    linear_extrude(t)
        hull() for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (w/2 - r), sy * (h/2 - r)]) circle(r = r, $fn = 96);
}

intersection() {
    board_cradle();
    translate([0, 0, 15.5])
        case_rrect(BM_W + 2*GROW, BM_H + 2*GROW, BM_R + GROW, 1.0);
}

// Does the far lip STILL HOLD after the board slides to one end of the wider
// pocket? This is the other half of the BM_FIT=2.0 change: opening the pocket
// buys assembly, and it can only be paid for by re-sizing BM_LIP_W. This probe
// checks the payment actually landed.
//
// NOTE THE INVERTED PASS SIGNAL. Every other probe in this folder is an
// interference check where EMPTY == good. This one asks whether material is
// PRESENT where the lip has to be, so NON-EMPTY == good. An empty result here
// means the clamps let go of the board.
//
// Arithmetic being verified:
//   pocket half-width = (BM_W + BM_FIT)/2 = (95.11 + 2.0)/2 = 48.555
//   board  half-width =  BM_W/2           =            47.555
//   lip inner edge    = 48.555 - BM_LIP_W = 48.555 - 2.8 =  45.755
//   grip, centred     = 47.555 - 45.755   = 1.80mm
//   grip, board shoved the full 1.0mm clearance to +X:
//                       far edge moves to -46.555, so grip = 0.80mm
// The slab below sits in the last 0.245mm of that worst-case 0.80mm. If solid
// is there, the far lip is still over the board with the board pushed as far
// away from it as the pocket allows.
use <D:/openVela/contest2026_043_CircuitForge/hardware/velapaw_feeder.scad>

BM_TOP_Z = 3 + 12 + 14.10;    // BM_BASE_T + BM_STANDOFF + BM_BOARD_T = 29.10
BM_LIP_T = 1.6;

intersection() {
    board_cradle();
    // x: just inboard of where the shifted board's far edge lands
    // y: inside a corner clamp's 14mm reach (OH/2 = 34.635, so 20.6..34.6)
    // z: within the lip band, clear of both faces
    translate([-46.0, 22, BM_TOP_Z + 0.2])
        cube([0.245, 8, BM_LIP_T - 0.4]);
}

